WITH metrics AS (SELECT *, SUM(cost) OVER (PARTITION BY status ORDER BY delivered_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_cost, LAG(cost, 1) OVER (ORDER BY shipped_date, id) AS prev_cost, CUME_DIST() OVER (PARTITION BY order_id ORDER BY cost NULLS LAST) AS cost_cume_dist FROM shipments) SELECT DATE_TRUNC('WEEK', delivered_date) AS week_start, PERCENTILE_APPROX(cost, 0.95) AS cost_p95, SORT_ARRAY(COLLECT_SET(carrier)) AS carrier_list, COUNT(DISTINCT id) AS distinct_ids FROM metrics GROUP BY 1
